INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine technische Dokumentation immer erforderlich?', 2, '[{"text": "Ja", "correct": true, "because": "Wichtig für Wartung und Verständnis"}, {"text": "Nein", "correct": false, "because": "Selten entbehrlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element priorisiere ich in einer Dokumentation für die Systemarchitektur?', 3, '[{"text": "Komponentenübersicht", "correct": true, "because": "Zeigt Struktur und Zusammenhänge"}, {"text": "Farbliche Gestaltung", "correct": false, "because": "Sekundär"}, {"text": "Kostenaufstellung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Konfigurationsdokumentation nützlich?', 5, '[{"text": "Detailgenauigkeit", "correct": true, "because": "Erleichtert Nachvollziehbarkeit"}, {"text": "Aktualität", "correct": true, "because": "Spiegelt aktuelles System wider"}, {"text": "Kurze Texte", "correct": false, "because": "Details wichtiger"}, {"text": "Allgemeinheit", "correct": false, "because": "Spezifität entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Systemarchitektur beschreibt Komponenten. b) Konfigurationsdetails sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Details essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer technischen Dokumentation?', 4, '[{"text": "Systemkomponenten", "correct": false, "because": "Kern der Architektur"}, {"text": "Konfigurationseinstellungen", "correct": false, "because": "Wichtig für Reproduktion"}, {"text": "Persönliche Meinungen", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Systemarchitektur ohne Diagramme auskommt?', 2, '[{"text": "Ja", "correct": true, "because": "Text allein möglich"}, {"text": "Nein", "correct": false, "because": "Diagramme oft hilfreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Konfigurationsdokumentation?', 3, '[{"text": "Reproduzierbarkeit", "correct": true, "because": "Ermöglicht Nachbau"}, {"text": "Kostensenkung", "correct": false, "because": "Sekundär"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Genauigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine technische Dokumentation?', 5, '[{"text": "Wartbarkeit", "correct": true, "because": "Erleichtert Fehlerbehebung"}, {"text": "Wissenstransfer", "correct": true, "because": "Teamwechsel unterstützt"}, {"text": "Geringer Aufwand", "correct": false, "because": "Erstellung zeitintensiv"}, {"text": "Schnelle Updates", "correct": false, "because": "Pflege nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Systemarchitektur zeigt Verbindungen. b) Konfiguration ist nur für Experten. Stimmt das?', 3, '[{"text": "Nur a) circumference": true, "because": "b) ist falsch, für alle relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Dokumentation der Systemarchitektur?', 4, '[{"text": "Komponentenbeschreibung", "correct": false, "because": "Kern der Architektur"}, {"text": "Verbindungsdetails", "correct": false, "because": "Zeigt Interaktionen"}, {"text": "Marketingtexte", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Konfigurationsdokumentation ohne Details nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Details sind essenziell"}, {"text": "Ja", "correct": false, "because": "Ohne Details unbrauchbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für eine technische Dokumentation entscheidend?', 4, '[{"text": "Klarheit", "correct": true, "because": "Verständlichkeit fördern"}, {"text": "Vollständigkeit", "correct": true, "because": "Alle Aspekte abdecken"}, {"text": "Kürze", "correct": false, "because": "Details wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Systemarchitektur nur Hardware beschreibt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software und Verbindungen"}, {"text": "Ja", "correct": false, "because": "Zu eng gefasst"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in einer Dokumentation für ein Netzwerk?', 3, '[{"text": "Topologie", "correct": true, "because": "Zeigt Struktur"}, {"text": "Kostenübersicht", "correct": false, "because": "Sekundär"}, {"text": "Kurze Zusammenfassung", "correct": false, "because": "Details wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Konfiguration enthält Einstellungen. b) Systemarchitektur ist nur für Entwickler.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, für alle relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine unvollständige technische Dokumentation?', 5, '[{"text": "Fehlende Nachvollziehbarkeit", "correct": true, "because": "Erschwert Wartung"}, {"text": "Wissensverlust", "correct": true, "because": "Teamwechsel problematisch"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Kein Nachteil"}, {"text": "Geringer Nutzen", "correct": false, "because": "Hauptproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Dokumentation für einen Server unwichtig?', 3, '[{"text": "Hardwarekonfiguration", "correct": false, "because": "Kerninformation"}, {"text": "Netzwerkeinstellungen", "correct": false, "because": "Wichtig für Zugriff"}, {"text": "Farbliche Gestaltung", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Soll eine technische Dokumentation regelmäßig aktualisiert werden?', 3, '[{"text": "Ja", "correct": true, "because": "Änderungen abbilden"}, {"text": "Nein", "correct": false, "because": "Veraltet schnell nutzlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Systemarchitektur nur Software beschreibt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardware und Verbindungen"}, {"text": "Ja", "correct": false, "because": "Zu eng gefasst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dokumentation wähle ich für ein Virtualisierungssystem?', 4, '[{"text": "Systemarchitektur und Konfiguration", "correct": true, "because": "Umfassend und detailliert"}, {"text": "Nur Architektur", "correct": false, "because": "Fehlen Details"}, {"text": "Kurze Notizen", "correct": false, "because": "Zu oberflächlich"}]');
